"""Compass constructions and the common/bounding circle in exercises 1178–1182, pp. 298–299 and 301."""
import argparse
import json
from math import cos, hypot, pi, sin, sqrt
from coordinate_curves import graph
from triangle_sine_area import area
from trigonometric_signs import grade
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/polygon-circle-applications.json'


def ring(n,r,offset):
    return [(r*cos(offset+2*pi*i/n),r*sin(offset+2*pi*i/n)) for i in range(n)]


def drawing(title,points,edges,center,r,focus):
    return graph(title,points,edges=edges,circle=(center,r),lines=[(points[a],points[b]) for a,b in focus])


def outline(names):
    return list(zip(names,names[1:]+names[:1],strict=True))


def polygon(title,n,R,kind='outside',also=0):
    phase=-pi/n;names=list('ABCDEF')[:n];vertices=ring(n,R,phase);pts=dict(zip(names,vertices,strict=True));pts['T']=(0,0)
    pts['H']=((vertices[0][0]+vertices[1][0])/2,(vertices[0][1]+vertices[1][1])/2)
    edges=outline(names)+[('T','A'),('T','H'),('A','H'),('B','H')]
    r=R if kind=='outside' else R*cos(pi/n)
    if also:
        other_R=r if kind=='outside' else r/cos(pi/also)
        extra=list('KLMNPQ')[:also];other=ring(also,other_R,.19-pi/also);pts.update(dict(zip(extra,other,strict=True)));edges+=outline(extra)
    pts['U']=(-R,-R-1);pts['W']=(-R+1,-R-1);edges.append(('U','W'))
    return drawing(title,pts,edges,'T',r,[('A','B'),('T','A' if kind=='outside' else 'H')])


def prompt(n,title,question,reason,hint,steps,views,checks,caption):
    page=[298,299] if n==117 else [301]
    e=area(n,None,page,question,reason,hint,steps,views,checks,title=title,refs=[114,115,116,117])
    e['source']['chapter']='XIII';e['review']['reviewer']='Издание Атанасяна 2023. Пункт 117 сверен с печатными с. 298–299, задачи №1178–1182 — с с. 301. Все граничные расстояния и обе разные роли окружности проверены на измеренных моделях.'
    e['visualization']['caption']=caption;e['visualization']['model']['description']=caption
    if not title:e['help'][1]['text']=hint
    return e


def doubled(title,n,base):
    # A and B are consecutive original vertices; K is the midpoint of their minor arc.
    old=['A','B',*['_old'+str(i) for i in range(2,n)]];new=['K',*['_new'+str(i) for i in range(1,n)]]
    p=dict(zip(old,ring(n,base,-pi/n),strict=True));p.update(dict(zip(new,ring(n,base,0),strict=True)))
    p['T']=(0,0);p['H']=(base*cos(pi/n),0)
    cycle=[k for pair in zip(old,new) for k in pair]
    return drawing(title,p,outline(old)+outline(cycle)+[('T','K'),('A','H'),('B','H')],'T',base,[('A','K'),('K','B'),('T','K')])


def construction():
    vs=[polygon('Шесть хорд, каждая равна радиусу',6,4),doubled('Из шести дуг получи двенадцать',6,4),doubled('Раздели дуги квадрата, чтобы получить восьмиугольник',4,4)]
    hint='У правильного шестиугольника длина одной хорды равна радиусу. Чтобы удвоить число сторон, добавь середину каждой малой дуги между соседними старыми вершинами.'
    return prompt(117,'Построение правильных многоугольников','Как циркулем и линейкой построить правильный шестиугольник по его стороне и как из построенного правильного n-угольника получить правильный 2n-угольник?',
        'Проведи окружность радиуса, равного заданной стороне, и последовательно отложи на ней шесть таких же хорд. Каждая образует с центром равносторонний треугольник, поэтому шесть поворотов по 60° замыкают фигуру. Для готового правильного n-угольника построй центр по двум соседним биссектрисам и описанную окружность. Серединный перпендикуляр к каждой стороне встречает её малую дугу в середине. Соедини старые и новые вершины по кругу: получилось 2n равных дуг и правильный 2n-угольник.',hint,[
        ('Отложи хорду без изменения раствора','Выбери на окружности A и откладывай циркулем хорды одного радиуса. Треугольник между двумя соседними точками и T равносторонний, значит поворот всегда 60°.','Хорду измеряй по прямой между точками; раствор не задаёт длину дуги.'),
        ('Построй новую вершину на окружности','У шестиугольника пусть H — середина AB. Прямая TH пересекает малую дугу AB в K. Точки H и K различны: H находится на стороне, K — на окружности. Равные дуги AK и KB дают новые равные хорды.','У окружности есть и второе пересечение с прямой: для этой стороны выбирается точка на её малой дуге.'),
        ('Используй метод на квадрате','Четыре старые вершины и четыре середины дуг образуют правильный восьмиугольник. Повтор даст 16 сторон. Удвоение действует для уже построенного n-угольника. В учебнике также отмечено, что правильный семиугольник нельзя построить только линейкой и циркулем, а семнадцатиугольник можно.','Правило удвоения само по себе не даёт построения для любого исходного числа сторон.')],vs,[
        ('Сколько сторон будет после одного удвоения шестиугольника?','12','Между двумя старыми соседями добавляется одна новая вершина.'),('Сколько сторон получится после двух удвоений квадрата?','16','Сначала 8, затем удвой ещё раз.')],'T — центр. Отмечены середина H стороны и точка K на дуге. Выделенные новые хорды AK и KB соединяют соседние вершины удвоенной фигуры.')


def triangle_square():
    r=2*sqrt(3);vs=[polygon('Исходный треугольник периметра 18',3,r),polygon('Треугольник и квадрат в одном круге',3,r,also=4),polygon('Обе вписанные фигуры после удвоения радиуса',3,2*r,also=4)]
    hint='Сначала найди сторону треугольника 18/3. Общей у двух фигур является величина R: для треугольника a=R√3, для квадрата a=R√2.'
    e=prompt(1178,None,'В одну окружность вписаны правильный треугольник периметра 18 см и квадрат. Вычисли сторону квадрата.',
        'Сторона треугольника равна 6. Поэтому R=6/√3=2√3 см. Сторона квадрата равна R√2=2√6 см. Именно общий радиус, а не равенство сторон или периметров, связывает фигуры.',hint,[
        ('Восстанови радиус по треугольнику','Периметр 18 делится на три. Сторона 6 противолежит центральному углу 120°, так что 6=2R sin 60°=R√3.','Деление 18 на четыре относилось бы к квадрату, а периметр задан для треугольника.'),
        ('Проверь квадрат по диагонали','Диагональ вписанного квадрата равна общему диаметру 2R. Если сторона x, то 2x²=4R², значит x=R√2. Здесь x²=24.','Сторона квадрата короче диаметра.'),
        ('Увеличь исходный периметр вдвое','Если треугольник имеет периметр 36, общий радиус и сторона квадрата также удваиваются. Новая сторона 4√6, а её квадрат 96.','Квадрат длины при удвоении возрастает вчетверо.')],vs,[
        ('Чему равна исходная сторона треугольника, см?','6','Раздели 18 на три.'),('Каков квадрат стороны квадрата при новом треугольном периметре 36?','96','Новая сторона 4√6.')],'Треугольник ABC и квадрат KLMN лежат на одной окружности. UW имеет длину 1. На втором чертеже обе фигуры видны одновременно.')
    return grade(e,['2√6','2sqrt(6)','2*sqrt(6)','√24','sqrt(24)'],hint,'Введи точную длину стороны квадрата, в см.')


def bounding_triangle(title,a,shift=0):
    r=a/sqrt(3);pts=dict(zip('ABC',ring(3,r,0),strict=True));pts['T']=(0,0)
    center='T'
    if shift:pts['J']=(shift,0);center='J'
    return drawing(title,pts,outline(list('ABC'))+[('T','A'),*( [(center,'B'),(center,'C')] if shift else [('T','B'),('T','C')])],center,r,[(center,'B'),(center,'C')])


def valve():
    vs=[bounding_triangle('Круг через три вершины, сторона 3',3),bounding_triangle('Сдвинь центр прежнего круга вправо',3,.5),bounding_triangle('Новая сторона сечения 6',6)]
    hint='Треугольное сечение должно целиком поместиться в круге. Для равностороннего треугольника минимальный круг описан вокруг него, его диаметр равен 2a/√3.'
    e=prompt(1179,None,'Сечение головки вентиля — правильный треугольник со стороной 3 см. Какой наименьший диаметр должен иметь круглый стержень, чтобы такое сечение поместилось в нём?',
        'Оптимальный круг имеет центр T треугольника и проходит через его вершины. При стороне a=3 радиус TA=a/√3=√3 см. Минимальный диаметр 2√3 см. Для обоснования минимума возьмём иной центр J: в среднем по трём вершинам V величина JV² равна JT²+TV², поскольку сумма трёх векторов из T к вершинам равна нулю. Значит хотя бы одно расстояние ≥√(JT²+TV²), больше исходного радиуса при J≠T.',hint,[
        ('Отличи круг заготовки от вписанного круга','Круглая заготовка должна содержать все три угла. Круг, касающийся сторон изнутри, оставил бы вершины снаружи. У точки T расстояние до каждой вершины равно √3.','Сравни расстояние до стороны и расстояние до вершины сечения.'),
        ('Объясни оптимальность центра','У трёх симметричных стрелок TA, TB, TC сумма равна нулю. После переноса начала в J среднее из квадратов JA, JB, JC равняется JT²+TA². При сдвиге центра хотя бы одна вершина станет дальше прежнего радиуса. Средний чертёж показывает именно это.','Проверка одного сдвига иллюстрирует результат; равенство средних квадратов доказывает его для любого сдвига.'),
        ('Проверь другой размер детали','При стороне 6 минимальный радиус равен 2√3 см, диаметр 4√3 см. Для него d²=48 см².','В задаче спрашивают диаметр, вдвое больший радиуса.')],vs,[
        ('Каков квадрат минимального радиуса для стороны 3?','3','Радиус равен √3.'),('Каков d² при новой стороне 6?','48','Возведи 4√3 в квадрат.')],'T — центр треугольника. Во втором примере J — другой центр, радиус оставлен прежним. Видно, какие вершины оказались за границей.')
    return grade(e,['2√3','2sqrt(3)','2*sqrt(3)','√12','sqrt(12)'],hint,'Введи точный минимальный диаметр в сантиметрах.')


def blank(title,w,h,offset=0):
    pts={'A':(-w/2,-h/2),'B':(w/2,-h/2),'C':(w/2,h/2),'D':(-w/2,h/2),'T':(offset,0),'H':(offset,-h/2),'K':(offset,h/2)}
    return drawing(title,pts,outline(list('ABCD'))+[('H','K')],'T',min(w,h)/2,[('H','K')])


def wood():
    vs=[blank('Квадратное сечение 6 на 6',6,6),blank('Прежний диаметр при сдвиге центра вправо',6,6,.75),blank('Новая прямоугольная заготовка 8 на 4',8,4)]
    hint='Теперь круг должен поместиться внутри квадрата. Две противоположные стороны расположены на расстоянии 6 см, поэтому поперечник круга не может быть больше 6 см.'
    e=prompt(1180,None,'Из квадратного бруса с поперечным сечением 6 см на 6 см вытачивают круглый стержень. Каков наибольший возможный диаметр?',
        'Целый круг лежит между двумя противоположными сторонами, отстоящими на 6 см, поэтому его диаметр не превышает 6 см. Круг с центром в центре квадрата и радиусом 3 касается всех четырёх сторон, значит диаметр 6 см достижим.',hint,[
        ('Установи верхнюю границу','Измерь ширину горизонтальной полосы между нижней и верхней сторонами. У любого круга разность высот его верхней и нижней точек в точности равна диаметру.','Диагональ квадрата длиннее стороны, но круг не может уместить свой диаметр только вдоль одной диагонали.'),
        ('Покажи, как достичь границы','Если центр расположен посередине квадрата, радиус 3 целиком помещается во всех направлениях. При сдвиге вправо без уменьшения радиуса правая часть круга выходит наружу.','Верхняя граница становится ответом после предъявления круга подходящего размера.'),
        ('Смени форму заготовки','У прямоугольника 8 на 4 меньшая ширина 4. В центре можно расположить круг диаметра 4. Теперь он касается двух горизонтальных сторон.','За достижимый диаметр отвечает меньшая из двух ширин.')],vs,[
        ('Каков радиус наибольшего круга в исходном квадрате?','3','Половина ширины 6.'),('Каков максимальный диаметр в прямоугольнике 8 на 4?','4','Сравни обе ширины прямоугольника.')],'H и K лежат на противоположных горизонтальных сторонах. Сопоставь положение круга с обеими вертикальными границами при сдвиге.')
    return grade(e,['6','6,0','6.0','6 см'],hint,'Введи наибольший диаметр, в см.')


def two_frames():
    vs=[polygon('Правильный шестиугольник со стороной 8',6,8,'inside'),polygon('Один круг касается обеих рамок',6,8,'inside',4),polygon('Уменьши шестиугольный периметр до 24',6,4,'inside',4)]
    hint='Обе фигуры описаны около одной окружности, значит общим является вписанный радиус r. Для шестиугольника он равен a√3/2. Сторона описанного квадрата равна 2r.'
    e=prompt(1181,None,'Около одной окружности описаны квадрат и правильный шестиугольник. Периметр последнего 48 см. Найди периметр квадрата.',
        'У шестиугольника сторона 48/6=8 см. Его вписанный радиус r=8 cos 30°=4√3 см. У описанного квадрата сторона 2r=8√3 см, поэтому периметр 32√3 см.',hint,[
        ('Найди расстояние до стороны шестиугольника','Центральный треугольник в правильном шестиугольнике равносторонний, его сторона 8. Высота к стороне равна 4√3. Она же является радиусом круга.','Большая окружность через вершины шестиугольника здесь не связывает обе фигуры.'),
        ('Перейди к квадрату','От одной стороны квадрата до противоположной — два радиуса. Таким образом a₄=8√3, P₄=4a₄=32√3.','Дважды умножь радиус по смыслу: сначала на два для стороны, затем сторону на четыре.'),
        ('Проверь подобие','Если первоначальный шестиугольный периметр 24 см, все длины уменьшатся вдвое. Получаем r=2√3 и периметр квадрата 16√3 см.','Не применяй квадрат коэффициента масштаба к периметру.')],vs,[
        ('Какова исходная сторона шестиугольника, см?','8','Раздели 48 на 6.'),('Каков коэффициент при √3 в новом периметре квадрата?','16','Новый радиус 2√3, периметр квадрата равен восьми радиусам.')],'ABCDEF и KLMN касаются одного круга. TH — радиус к стороне шестиугольника, TA — расстояние до его вершины. Отрезок UW соответствует 1.')
    return grade(e,['32√3','32sqrt(3)','32*sqrt(3)','√3072','sqrt(3072)'],hint,'Введи точный периметр квадрата в сантиметрах.')


def radius_ratio():
    vs=[polygon('Исходный правильный треугольник с R=4',3,4),polygon('Та же фигура с выделенной вписанной окружностью',3,4,'inside'),polygon('Новый правильный треугольник с R=6',3,6,'inside')]
    hint='T — общий центр двух окружностей, H — середина стороны AB. В прямоугольном TAH угол при T равен половине 120°, поэтому TH=TA cos 60°.'
    e=prompt(1182,None,'Около правильного треугольника описана окружность радиуса R, а внутри него вписана окружность радиуса r. Докажи R=2r.',
        'Для соседних вершин A,B центральный угол ATB равен 120°. Высота TH в равнобедренном TAB является также биссектрисой, так что ATH=60°. При TA=R и TH=r получаем r=R cos 60°=R/2. Значит R=2r.',hint,[
        ('Назови обе длины','TA идёт от общего центра T к вершине треугольника и имеет длину R. TH опущен на сторону AB и является радиусом вписанной окружности r.','Обе окружности с одним центром, но длины их радиусов различаются.'),
        ('Используй половину центрального угла','Между TA и TB угол 360°/3=120°. Отрезок TH делит его пополам, поэтому TH/TA=cos 60°=1/2. При R=4 на среднем чертеже r=2.','Косинус берётся от 60°, а не от полного угла 120°.'),
        ('Проверь при новом радиусе','Если R=6, то r=3. Отношение R/r=2 сохраняется для любого размера правильного треугольника, поскольку угол в доказательстве не изменяется.','Покажи и общий переход r=R/2, и числовую проверку.')],vs,[
        ('Каков r при исходном R=4?','2','Возьми половину 4.'),('Чему равен новый r при R=6?','3','Умножь 6 на cos 60°.')],'TA идёт к вершине, TH — к середине стороны. Переключение показывает, какая окружность проходит через A и какая касается стороны в H.')
    e['answer']['prompt']='Докажи равенство радиусов с использованием угла ATH и косинуса.'
    return e


def build():
    return {'bookId':BOOK,'lessons':[construction(),triangle_square(),valve(),wood(),two_frames(),radius_ratio()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
    text=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==text
    else:OUT.write_text(text)
